def get_usb_storage_devices():
    """Scan for connected USB storage devices and return their names."""
    devices = []

    # Platform-specific detection
    if sys.platform.startswith('linux'):
        # On Linux, check /sys/block for USB devices
        try:
            for item in os.listdir('/sys/block/'):
                if item.startswith('sd') and not item.endswith(('1', '2', '3', '4', '5', '6', '7', '8', '9')):
                    # Check if it's a USB device by looking at sysfs
                    device_path = f'/sys/block/{item}'
                    if os.path.exists(f'{device_path}/device/usb'):
                        # Get device name from /dev
                        dev_name = f'/dev/{item}'
                        if os.path.exists(dev_name):
                            devices.append(dev_name)
        except (OSError, PermissionError) as e:
            logger.warning(f"Error accessing Linux USB devices: {e}")

    elif sys.platform == 'darwin':
        # On macOS, use diskutil to list disks
        try:
            result = subprocess.run(['diskutil', 'list', 'physical'], 
                                  capture_output=True, text=True, timeout=10)
            lines = result.stdout.split('\n')
            for line in lines:
                if 'USB' in line and '/dev/disk' in line:
                    # Extract device name
                    parts = line.split()
                    for part in parts:
                        if part.startswith('/dev/disk'):
                            devices.append(part)
        except (subprocess.SubprocessError, subprocess.TimeoutExpired, FileNotFoundError) as e:
            logger.warning(f"Error accessing macOS USB devices: {e}")

    elif sys.platform == 'win32':
        # On Windows, check drive letters for removable media
        import string
        try:
            for letter in string.ascii_uppercase:
                drive = f"{letter}:\\"
                if os.path.exists(drive):
                    try:
                        # Check if it's removable (USB)
                        import ctypes
                        from ctypes import wintypes

                        kernel32 = ctypes.windll.kernel32
                        win32_file = kernel32.GetDriveTypeW(drive)
                        if win32_file == 2:  # DRIVE_REMOVABLE
                            devices.append(drive)
                    except Exception as e:
                        logger.warning(f"Error checking Windows drive {drive}: {e}")
        except Exception as e:
            logger.warning(f"Error accessing Windows USB devices: {e}")

    return devices

def get_device_files(device_path):
    """Get file information from a device path."""
    files_info = []

    try:
        # For Linux/macOS, we need to mount the device or access it directly
        # For simplicity, we'll look at common mount points
        if sys.platform.startswith('linux'):
            # Try to access the device directly if it's a mounted filesystem
            if os.path.exists(device_path):
                try:
                    for root, dirs, files in os.walk(device_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            try:
                                stat = os.stat(file_path)
                                file_info = {
                                    'path': file_path,
                                    'size': stat.st_size,
                                    'created': datetime.fromtimestamp(stat.st_ctime).isoformat(),
                                    'modified': datetime.fromtimestamp(stat.st_mtime).isoformat()
                                }
                                files_info.append(file_info)
                            except (OSError, PermissionError) as e:
                                logger.debug(f"Permission error accessing file {file_path}: {e}")
                                continue
                except Exception as e:
                    logger.warning(f"Error walking Linux filesystem {device_path}: {e}")

        elif sys.platform == 'darwin':
            # Try to access the device directly
            if os.path.exists(device_path):
                try:
                    for root, dirs, files in os.walk(device_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            try:
                                stat = os.stat(file_path)
                                file_info = {
                                    'path': file_path,
                                    'size': stat.st_size,
                                    'created': datetime.fromtimestamp(stat.st_ctime).isoformat(),
                                    'modified': datetime.fromtimestamp(stat.st_mtime).isoformat()
                                }
                                files_info.append(file_info)
                            except (OSError, PermissionError) as e:
                                logger.debug(f"Permission error accessing file {file_path}: {e}")
                                continue
                except Exception as e:
                    logger.warning(f"Error walking macOS filesystem {device_path}: {e}")

        elif sys.platform == 'win32':
            # Windows - check if it's a valid drive
            if os.path.exists(device_path) and os.path.isdir(device_path):
                try:
                    for root, dirs, files in os.walk(device_path):
                        for file in files:
                            file_path = os.path.join(root, file)
                            try:
                                stat = os.stat(file_path)
                                file_info = {
                                    'path': file_path,
                                    'size': stat.st_size,
                                    'created': datetime.fromtimestamp(stat.st_ctime).isoformat(),
                                    'modified': datetime.fromtimestamp(stat.st_mtime).isoformat()
                                }
                                files_info.append(file_info)
                            except (OSError, PermissionError) as e:
                                logger.debug(f"Permission error accessing file {file_path}: {e}")
                                continue
                except Exception as e:
                    logger.warning(f"Error walking Windows filesystem {device_path}: {e}")

    except Exception as e:
        logger.warning(f"Unexpected error accessing device {device_path}: {e}")

    return files_info

def send_to_server(data, url="http://localhost:8080/api/usb-data"):
    """Send collected data to a remote server endpoint."""
    try:
        import urllib.request
        import urllib.error

        json_data = json.dumps(data).encode('utf-8')
        req = urllib.request.Request(url, data=json_data)
        req.add_header('Content-Type', 'application/json')

        with urllib.request.urlopen(req, timeout=10) as response:
            return True, response.status

    except urllib.error.URLError as e:
        logger.error(f"Network error sending data to server: {e}")
        return False, str(e)
    except Exception as e:
        logger.error(f"Error sending data to server: {e}")
        return False, str(e)

