    def list_files(self, directory):
        """List all files in the specified directory."""
        try:
            files = os.listdir(directory)
            result = []
            for file in files:
                file_path = os.path.join(directory, file)
                if os.path.isfile(file_path):
                    result.append(file)
            return result
        except OSError as e:
            return {"error": f"Cannot access directory '{directory}': {e}"}

    def read_file(self, filepath):
        """Read and display the contents of a file."""
        try:
            with open(filepath, 'r') as f:
                content = f.read()
            return content
        except OSError as e:
            return {"error": f"Cannot read file '{filepath}': {e}"}

    def delete_file(self, filepath):
        """Delete a file."""
        try:
            os.remove(filepath)
            return {"success": f"Successfully deleted '{filepath}'"}
        except OSError as e:
            return {"error": f"Cannot delete file '{filepath}': {e}"}

    def get_metadata(self, filepath):
        """Extract metadata from a file if it exists."""
        try:
            with open(filepath, 'rb') as f:
                content = f.read()

            # Look for metadata marker
            metadata_marker = b'---METADATA---'
            marker_pos = content.rfind(metadata_marker)

            if marker_pos != -1:
                metadata_start = marker_pos + len(metadata_marker)
                metadata_json = content[metadata_start:].decode('utf-8')
                return json.loads(metadata_json)
        except Exception:
            pass
        return None

    def add_metadata(self, filepath):
        """Add or update metadata to a file."""
        try:
            # Get existing metadata if any
            existing_metadata = self.get_metadata(filepath)

            # Create new metadata
            metadata = {
                'id': str(uuid.uuid4()),
                'last_modified': datetime.now().isoformat(),
                'version': existing_metadata['version'] + 1 if existing_metadata and 'version' in existing_metadata else 1
            }

            # Read existing file content
            with open(filepath, 'rb') as f:
                content = f.read()

            # Prepare metadata section
            metadata_section = f"\n---METADATA---{json.dumps(metadata, indent=2)}"

            # Write back with metadata
            with open(filepath, 'wb') as f:
                f.write(content)
                f.write(metadata_section.encode('utf-8'))

            return {"success": f"Metadata added/updated for '{filepath}'", "metadata": metadata}

        except OSError as e:
            return {"error": f"Cannot modify file '{filepath}': {e}"}

    def show_metadata(self, filepath):
        """Display metadata from a file."""
        metadata = self.get_metadata(filepath)
        if metadata:
            return {"metadata": metadata}
        else:
            return {"error": f"No metadata found in '{filepath}'"}

    def send_heartbeat(self):
        """Send heartbeat to server."""
