                        "output": result.stdout,
                        "error": result.stderr,
                        "returncode": result.returncode
                    }
                else:
                    return {"success": False, "error": "No command provided"}
            elif cmd_type == "file_operation":
                op_type = command_data.get("operation")
                filepath = command_data.get("filepath")

                if op_type == "read":
                    return {"success": True, "content": self.read_file(filepath)}
                elif op_type == "list":
