    def __init__(self, log_file_path: str = 'infect_log.txt'):
        self.log_file_path = log_file_path
        self.bytes_appended = 0
        self.log_entries_written = 0

    def append_to_file(self, file_path: str, data: str, dry_run: bool = False) -> int:
        """Append data to a file and return the number of bytes appended."""
        if not dry_run:
            try:
                with open(file_path, 'a') as file:
                    file.write(data)
                return len(data.encode('utf-8'))
            except PermissionError:
                raise Exception(f"Permission denied: Cannot write to {file_path}")
            except FileNotFoundError:
                raise Exception(f"File not found: {file_path}")
            except Exception as e:
                raise Exception(f"Error appending to file: {e}")
        else:
            return len(data.encode('utf-8'))

    def log_append_operation(self, append_data: str, payload_size: int, file_path: str, dry_run: bool = False) -> None:
        """Log append operation to infect_log.txt."""
        if not dry_run:
            try:
                # Check if log file exists to determine if we need headers
                file_exists = os.path.exists(self.log_file_path)

                with open(self.log_file_path, 'a', newline='') as log_file:
                    writer = csv.writer(log_file)

                    # Write header if file doesn't exist
                    if not file_exists:
                        writer.writerow(['append', 'payload', 'file'])

                    # Write log entry
                    writer.writerow([append_data, str(payload_size), file_path])

                self.log_entries_written += 1
            except PermissionError:
                raise Exception(f"Permission denied: Cannot write to log file {self.log_file_path}")
            except Exception as e:
                raise Exception(f"Error writing to log file: {e}")

    def run(self, file_path: str, data: str, print_success: bool = False, 
            dry_run: bool = False, summary_only: bool = False) -> None:
        """Execute the append operation with logging."""
        try:
            # Validate file path
            if not os.path.exists(os.path.dirname(file_path)) and os.path.dirname(file_path):
                os.makedirs(os.path.dirname(file_path), exist_ok=True)

            # Perform append operation
            self.bytes_appended = self.append_to_file(file_path, data, dry_run)

            # Log operation
            if not dry_run:
                self.log_append_operation(data, self.bytes_appended, file_path)

            # Print success message if requested
            if print_success and not dry_run:
                print(f"Data successfully appended to {file_path}")

            # Print summary
            if not summary_only:
                print(f"Summary: {self.bytes_appended} bytes appended to {file_path}")
                if not dry_run:
                    print(f"Log entry added to {self.log_file_path}")
                else:
                    print("Dry run completed - no changes made")

        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

